using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize]public class ActivitiesController(ApplicationDbContext db,IAuditService audit):Controller{private string? CurrentUserId => User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;public async Task<IActionResult>Index(){var q=db.Activities.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.AssignedTo==CurrentUserId);return View(await q.OrderByDescending(x=>x.ActivityDate).ToListAsync());}public IActionResult Create()=>View(new Activity());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Activity m){if(!ModelState.IsValid)return View(m);m.AssignedTo=CurrentUserId;db.Add(m);await db.SaveChangesAsync();await audit.WriteAsync("Create","Activity",m.ActivityId.ToString());return RedirectToAction(nameof(Index));}}
